# Pair2/3 components are fragmented because shape cells aren't 4-connected (diagonal contact). Redo with 8-conn.
def comps8(g,color):
    H=len(g);W=len(g[0]);st=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and (r,c) not in st:
                q=[(r,c)];cl=[]
                while q:
                    a,b=q.pop()
                    if (a,b) in cl: continue
                    cl.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and g[x][y]==color and (x,y) not in cl: q.append((x,y))
                st|=set(cl); out.append(sorted(cl))
    return out
